const SIGIL_POINTS = 5
const SIGIL_INNER_RATIO = (3 - Math.sqrt(5)) / 2

// Downward tip first, then clockwise. The inner vertices are the intersections
// of the pentagram's chords, so the slots sit on its strokes, not on fake links.
export const SIGIL_OUTLINE: readonly Point[] = Array.from({ length: 2 * SIGIL_POINTS }, (_, i) => {
  const angle = Math.PI / 2 + i * Math.PI / SIGIL_POINTS
  const radius = i % 2 ? SIGIL_INNER_RATIO : 1
  return { x: radius * Math.cos(angle), y: radius * Math.sin(angle) }
})

