/** Fill the star's tips, then subdivide its perimeter as the roster grows. */
export function spaceSigilTopology(bounds: ReadonlyMap<string, NodeBounds>) {
  const endpoints = [...bounds.keys()].filter((id) => id !== HUB_ID).sort()
  const smallRosters: readonly (readonly number[])[] = [[], [0], [2, 8], [0, 4, 6], [2, 4, 6, 8]]
  const slots = smallRosters[endpoints.length]?.map((i) => SIGIL_OUTLINE[i]) ??
    Array.from({ length: SIGIL_POINTS }, (_, tip) => {
      // Each section gets either floor(n/5) or ceil(n/5) cards, including its tip.
      const count = Math.floor((tip + 1) * endpoints.length / SIGIL_POINTS) -
        Math.floor(tip * endpoints.length / SIGIL_POINTS)
      return Array.from({ length: count }, (_, i) => {
        const offset = 2 * i / count
        const start = 2 * tip + Math.floor(offset)
        const fraction = offset % 1
        const a = SIGIL_OUTLINE[start]
        const b = SIGIL_OUTLINE[(start + 1) % SIGIL_OUTLINE.length]
        return { x: a.x + (b.x - a.x) * fraction, y: a.y + (b.y - a.y) * fraction }
